<?php use FilamentManager\Core\View; ?>
<?php if (!empty($update['available'])): ?><div class="notice warning update-banner"><strong><?= View::e(View::t('new_version_available',['version'=>$update['latest']])) ?></strong><a class="button action-button" href="<?= View::e($basePath) ?>/admin/settings"><?= View::t('show_update') ?></a></div><?php endif; ?>
<div class="toolbar"><div><h1><?= View::t('dashboard') ?></h1><p class="muted"><?= count($printers) ?> × 3D</p></div><?php if (in_array($app->auth()->user()['role'], ['admin','manager'], true)): ?><a class="button" href="<?= View::e($basePath) ?>/printers/new">＋ <?= View::t('add_printer') ?></a><?php endif; ?></div>
<?php if (!$printers): ?><section class="empty"><h2><?= View::t('no_printers') ?></h2><?php if (in_array($app->auth()->user()['role'], ['admin','manager'], true)): ?><a class="button" href="<?= View::e($basePath) ?>/printers/new"><?= View::t('add_printer') ?></a><?php endif; ?></section><?php else: ?><div class="cards">
<?php foreach ($printers as $printerIndex=>$printer): $available=($printer['status']??'active')==='active'; ?><article class="card printer-card<?= $available?'':' is-unavailable' ?>"><div class="toolbar"><div><h2><?= View::e($printer['name']) ?></h2><small><?= View::e(trim(($printer['manufacturer'] ?? '') . ' ' . ($printer['model'] ?? ''))) ?></small></div><div class="printer-actions"><?php if(!$available): ?><span class="status-badge status-<?= View::e($printer['status']) ?>"><?= View::t('printer_status_'.$printer['status']) ?></span><?php endif; ?><?php if($printerSortMode==='custom'&&in_array($app->auth()->user()['role'],['admin','manager'],true)): ?><div class="sort-actions"><form method="post" action="<?= View::e($basePath) ?>/printers/<?= View::e($printer['id']) ?>/move"><?= View::csrf() ?><input type="hidden" name="direction" value="up"><button class="secondary-button sort-button" aria-label="<?= View::t('move_up') ?>" title="<?= View::t('move_up') ?>" <?= $printerIndex===0?'disabled':'' ?>>↑</button></form><form method="post" action="<?= View::e($basePath) ?>/printers/<?= View::e($printer['id']) ?>/move"><?= View::csrf() ?><input type="hidden" name="direction" value="down"><button class="secondary-button sort-button" aria-label="<?= View::t('move_down') ?>" title="<?= View::t('move_down') ?>" <?= $printerIndex===count($printers)-1?'disabled':'' ?>>↓</button></form></div><?php endif; ?><?php if (in_array($app->auth()->user()['role'], ['admin','manager'], true)): ?><a class="button secondary-button action-button" href="<?= View::e($basePath) ?>/printers/<?= View::e($printer['id']) ?>/edit"><?= View::t('edit') ?></a><?php endif; ?></div></div>
<?php foreach ($slotsByPrinter[$printer['id']] ?? [] as $slot): $hex=preg_match('/^#[0-9A-Fa-f]{6}$/',(string)$slot['color_hex'])?$slot['color_hex']:'#d0d5dd'; ?><div class="slot-row"><input class="color-swatch" type="color" value="<?= View::e($hex) ?>" disabled aria-label="<?= View::e($slot['color_name'] ?: View::t('color')) ?>"><span><strong><?= View::e($slot['material_type'] ?: '—') ?></strong> <?= View::e($slot['color_name'] ?: '') ?><small> · <?= View::t('slot') ?> <?= View::e($slot['slot_number']) ?></small></span><strong><?= $slot['current_net_weight_g'] !== null ? View::e(number_format((float)$slot['current_net_weight_g'],0,',',' ')) . ' g' : '—' ?></strong></div><?php endforeach; ?>
</article><?php endforeach; ?></div><?php endif; ?>
